<body>
    <div id="content"><div class="loading">— 古卷展开中 —</div></div>

    <script>
        var rawData = `$1`;

        function detectType(d) {
            if (d.indexOf('<enemy_data>') !== -1) return 'enemy';
            if (d.indexOf('<npc_data>') !== -1) return 'npc';
            if (d.indexOf('<summon_data>') !== -1) return 'summon';
            if (d.indexOf('<contract_data>') !== -1) return 'contract';
            if (d.indexOf('<cluster_data>') !== -1) return 'cluster';
            return null;
        }

        function parseEnemy(raw) {
            var r = {name:'',type:'',race:'',tier:'',level:0,hpCur:0,hpMax:0,def:0,spd:0,init:0,
                     attr:{str:0,dex:0,con:0,int:0,wis:0,cha:0},attacks:[],abilities:[],
                     ougis:[],powers:[],mechanics:[],
                     weak:'',resist:'',immune:'',loot:[],exp:0,appear:'',status:''};
            var m = raw.match(/<enemy_data>([\s\S]*?)<\/enemy_data>/);
            if(!m) return r;
            var t = m[1];
            var g = function(re){var x=t.match(re);return x?x[1]:'';};
            r.name=g(/\[名称\|([^\]]+)\]/);
            r.type=g(/\[种类\|([^\]]+)\]/);
            r.race=g(/\[种族\|([^\]]+)\]/);
            r.tier=g(/\[等阶\|([^\]]+)\]/);
            r.level=parseInt(g(/\[等级\|([^\]]+)\]/))||0;
            var hp=t.match(/\[HP\|([^\|]+)\|([^\]]+)\]/);
            if(hp){r.hpCur=parseInt(hp[1])||0;r.hpMax=parseInt(hp[2])||0;}
            r.def=parseInt(g(/\[防御值\|([^\]]+)\]/))||0;
            r.spd=parseInt(g(/\[移动速度\|([^\]]+)\]/))||0;
            r.init=parseInt(g(/\[先攻修正\|([^\]]+)\]/))||0;
            var at=t.match(/\[属性\|力量([^\|]+)\|敏捷([^\|]+)\|体质([^\|]+)\|智力([^\|]+)\|感知([^\|]+)\|魅力([^\]]+)\]/);
            if(at){r.attr={str:parseInt(at[1])||0,dex:parseInt(at[2])||0,con:parseInt(at[3])||0,int:parseInt(at[4])||0,wis:parseInt(at[5])||0,cha:parseInt(at[6])||0};}
            var ax=/\[攻击\|([^\|]+)\|([^\|]+)\|([^\|]+)\|([^\|]+)\|([^\]]*)\]/g,am;
            while((am=ax.exec(t))!==null){r.attacks.push({name:am[1],type:am[2],hit:am[3],dmg:am[4],eff:am[5]});}
            var bx=/\[能力\|([^\|]+)\|([^\]]+)\]/g,bm;
            while((bm=bx.exec(t))!==null){r.abilities.push({name:bm[1],desc:bm[2]});}
            // 奥义（史诗级大招）/ 权能（传说级法则之力）：支持多条 [奥义|...] [权能|...]
            var ox=/\[奥义\|([^\]]+)\]/g,om;
            while((om=ox.exec(t))!==null){r.ougis.push(om[1]);}
            var px=/\[权能\|([^\]]+)\]/g,pm;
            while((pm=px.exec(t))!==null){r.powers.push(pm[1]);}
            var mx=/\[机制\|([^\]]+)\]/g,mm;
            while((mm=mx.exec(t))!==null){r.mechanics.push(mm[1]);}
            r.weak=g(/\[弱点\|([^\]]*)\]/);
            r.resist=g(/\[抗性\|([^\]]*)\]/);
            r.immune=g(/\[免疫\|([^\]]*)\]/);
            var lx=/\[战利品\|([^\|]+)\|([^\]]+)\]/g,lm;
            while((lm=lx.exec(t))!==null){r.loot.push({item:lm[1],rate:lm[2]});}
            r.exp=parseInt(g(/\[经验值\|([^\]]+)\]/))||0;
            r.appear=g(/\[外貌\|([^\]]+)\]/);
            r.status=g(/\[状态\|([^\]]*)\]/);
            return r;
        }

        function parseNPC(raw) {
            var r = {name:'',race:'',gender:'',age:'',identity:'',faction:'',
                     tier:'',level:0,hpCur:0,hpMax:0,def:0,spd:0,init:0,
                     attr:{str:0,dex:0,con:0,int:0,wis:0,cha:0},attacks:[],abilities:[],
                     ougis:[],powers:[],mechanics:[],
                     appear:'',personality:'',bgStory:'',blessing:'',attitude:'',affinity:50,functions:[],status:'',loadVar:'',
                     equips:[],items:[]};
            var m = raw.match(/<npc_data>([\s\S]*?)<\/npc_data>/);
            if(!m) return r;
            var t = m[1];
            var g = function(re){var x=t.match(re);return x?x[1]:'';};
            r.name=g(/\[姓名\|([^\]]+)\]/);
            r.race=g(/\[种族\|([^\]]+)\]/);
            r.gender=g(/\[性别\|([^\]]+)\]/);
            r.age=g(/\[年龄\|([^\]]+)\]/);
            r.identity=g(/\[身份\|([^\]]+)\]/);
            r.faction=g(/\[所属势力\|([^\]]+)\]/);
            r.tier=g(/\[等阶\|([^\]]+)\]/);
            r.level=parseInt(g(/\[等级\|([^\]]+)\]/))||0;
            var hp=t.match(/\[HP\|([^\|]+)\|([^\]]+)\]/);
            if(hp){r.hpCur=parseInt(hp[1])||0;r.hpMax=parseInt(hp[2])||0;}
            r.def=parseInt(g(/\[防御值\|([^\]]+)\]/))||0;
            r.spd=parseInt(g(/\[移动速度\|([^\]]+)\]/))||0;
            r.init=parseInt(g(/\[先攻修正\|([^\]]+)\]/))||0;
