        /* ========== 获取酒馆助手 ========== */
        function getHelper() {
            return window.TavernHelper || window.parent?.TavernHelper || window;
        }

        /* ========== 载入变量功能 ========== */
        function loadAsNPC(npcData) {
            var helper = getHelper();
            if (typeof helper.insertOrAssignVariables !== 'function') {
                showResult('load-result', false, '✗ 未检测到 TavernHelper API');
                return;
            }
            var payload = { stat_data: { 主要NPC: {} } };
            payload.stat_data.主要NPC[npcData.name] = {
                好感度: npcData.affinity || 50,
                心里话: ''
            };
            helper.insertOrAssignVariables(payload, { type: 'message', message_id: 'latest' });
            showResult('load-result', true, '✓ 已作为普通NPC载入变量');
        }

        function loadAsCompanion(npcData) {
            var helper = getHelper();
            if (typeof helper.insertOrAssignVariables !== 'function') {
                showResult('load-result', false, '✗ 未检测到 TavernHelper API');
                return;
            }
            // 将 NPC 的 [能力|...] 映射为状态栏「技能」字段
            var compSkills = {};
            (npcData.abilities || []).forEach(function(ab) {
                if (ab && ab.name) compSkills[ab.name] = { 描述: ab.desc || '', 等级: 1 };
            });
            // 将 NPC 的 [装备|...] 映射为状态栏「装备栏」五槽（头部/颈部/躯干/腿部/双手）
            var compEquips = { 头部: {}, 颈部: {}, 躯干: {}, 腿部: {}, 双手: {} };
            (npcData.equips || []).forEach(function(eq) {
                if (eq && eq.slot && compEquips[eq.slot] !== undefined && eq.name) {
                    compEquips[eq.slot] = {
                        物品大类: '防具', 品阶: '普通', 装备位: eq.slot, 数量: 1,
                        其它说明: eq.desc || '', 面板效果: {}, 附加词条: {},
                        交易与物理属性: { 数量: 1, 可否堆叠: '否', 价格: '', 重量: '' },
                        描述: eq.desc || '', 物品名: eq.name
                    };
                }
            });
            // 将 NPC 的 [随身物品|...] 映射为状态栏「物品栏」
            var compItems = {};
            (npcData.items || []).forEach(function(it) {
                if (it && it.name) {
                    compItems[it.name] = {
                        物品大类: '一般物品', 品阶: '普通', 装备位: '无', 数量: it.qty || 1,
                        其它说明: it.desc || '', 面板效果: {}, 附加词条: {},
                        交易与物理属性: { 数量: it.qty || 1, 可否堆叠: '是', 价格: '', 重量: '' },
                        描述: it.desc || ''
                    };
                }
            });
            var payload = { stat_data: { 同伴: {} } };
            payload.stat_data.同伴[npcData.name] = {
                好感度: npcData.affinity || 50,
                心里话: '',
                种族: npcData.race || '',
                身份: npcData.identity || '',
                所属势力: npcData.faction || '',
                等阶: npcData.tier || '普通',
                外貌: npcData.appear || '',
                性格: npcData.personality || '',
                背景故事: npcData.bgStory || '',
                基础属性: {
                    力量: npcData.attr.str || 10,
                    敏捷: npcData.attr.dex || 10,
                    体质: npcData.attr.con || 10,
                    智力: npcData.attr.int || 10,
                    感知: npcData.attr.wis || 10,
                    魅力: npcData.attr.cha || 10,
                    未分配点数: 0
                },
                基础状态: {
                    HP: { 当前: npcData.hpCur || 0, 最大: npcData.hpMax || 0 },
                    MP: { 当前: 0, 最大: 0 },
                    SP: { 当前: 0, 最大: 0 },
                    自身状态: {},
                    经验值: { 当前: 0, 升级所需: 100 },
                    职业信息: {},
                    冒险者等级: 'F',
                    总等级: npcData.level || 1,
                    待分配职业等级: 0
                },
                防御值: npcData.def || 10,
                技能: compSkills,
                物品栏: compItems,
                装备栏: compEquips
            };
            helper.insertOrAssignVariables(payload, { type: 'message', message_id: 'latest' });
            showResult('load-result', true, '✓ 已作为同伴载入变量（含完整数据，符合状态栏格式）');
        }

