            if(d.weak||d.resist||d.immune){h+='<div class="sec-head">◆ 弱点与抗性</div><div class="tag-area">';if(d.weak)h+='<span class="r-tag r-weak">弱点: '+d.weak+'</span>';if(d.resist)h+='<span class="r-tag r-resist">抗性: '+d.resist+'</span>';if(d.immune)h+='<span class="r-tag r-immune">免疫: '+d.immune+'</span>';h+='</div>';}
            if(d.personality){h+='<div class="sec-head">◆ 性格</div><div class="trait-area">';var ts=d.personality.split(/[,，、]/);for(var x=0;x<ts.length;x++){var tr=ts[x].trim();if(tr)h+='<span class="trait-chip">'+tr+'</span>';}h+='</div>';}
            if(d.appear){h+='<div class="sec-head">◆ 外貌</div><div class="appear-block"><span class="appear-text">'+d.appear+'</span></div>';}
            if(d.bgStory){h+='<div class="sec-head">◆ 背景故事</div><div class="bg-story-block"><div class="bg-story-text">'+d.bgStory+'</div></div>';}
            if(d.status){h+='<div class="status-block"><div class="status-label">⚠ 状态效果</div><div class="status-text">'+d.status+'</div></div>';}

            /* 一键写入状态栏按钮 */
            h+='<div class="load-var-area contract-write">';
            h+='<div class="load-var-title">📥 写入状态栏</div>';
            h+='<div class="load-var-btns">';
            h+='<button class="load-var-btn btn-contract" id="btn-write-contract">一键写入状态栏（同伴栏·契约兽）</button>';
            h+='</div>';
            h+='<div class="load-result" id="load-result"></div>';
            h+='</div>';

            h+='</div>';
            h+='<div class="panel-foot"><div class="faction-area">⚜ '+(d.faction||'无')+'</div></div>';
            h+='</div></div></div>';
            return h;
        }

        /* ========== 契约兽按钮与元素切换 ========== */
        function bindContractActions(d) {
            var btnContract = document.getElementById('btn-write-contract');
            if(btnContract) btnContract.addEventListener('click', function(){ loadAsContract(d); });
            var sw = document.getElementById('elem-switch');
            if(sw) sw.addEventListener('click', function(ev){
                var t = ev.target;
                var btn = t && t.closest ? t.closest('.elem-btn') : (t && t.classList && t.classList.contains('elem-btn') ? t : null);
                if(!btn) return;
                d.element = btn.getAttribute('data-elem');
                document.getElementById('content').innerHTML = renderContract(d);
                bindContractActions(d);
            });
        }

        /* ========== 启动 ========== */
        (function(){
            try {
                var dtype = detectType(rawData);
                if(dtype==='enemy'){
                    document.getElementById('content').innerHTML = renderEnemy(parseEnemy(rawData));
                } else if(dtype==='npc'){
                    var npcData = parseNPC(rawData);
                    document.getElementById('content').innerHTML = renderNPC(npcData);

                    var btnNpc = document.getElementById('btn-load-npc');
                    var btnComp = document.getElementById('btn-load-comp');
                    if(btnNpc) btnNpc.addEventListener('click', function(){ loadAsNPC(npcData); });
                    if(btnComp) btnComp.addEventListener('click', function(){ loadAsCompanion(npcData); });

                    var btnWb = document.getElementById('btn-create-wb');
                    if(btnWb) btnWb.addEventListener('click', function(){ addNpcToWorldbook(npcData); });
                } else if(dtype==='summon'){
                    var summonData = parseSummon(rawData);
                    document.getElementById('content').innerHTML = renderSummon(summonData);

                    var btnSummon = document.getElementById('btn-write-summon');
                    if(btnSummon) btnSummon.addEventListener('click', function(){ loadAsSummon(summonData); });
                } else if(dtype==='contract'){
                    var contractData = parseContract(rawData);
                    document.getElementById('content').innerHTML = renderContract(contractData);
                    bindContractActions(contractData);
                } else if(dtype==='cluster'){
                    document.getElementById('content').innerHTML = renderCluster(parseCluster(rawData));
                } else {
                    document.getElementById('content').innerHTML = '<div class="loading">— 无法识别古卷内容 —</div>';
                }
            } catch(e) {
                document.getElementById('content').innerHTML = '<div class="loading">— 古卷破损：'+e.message+' —</div>';
            }
        })();
    </script>
</body>
</html>
